+    display: flex;
+    gap: 4px;
+    background: #2f3136;
+    border: 1px solid #4f545c;
+    border-radius: 6px;
+    padding: 6px 8px;
+    box-shadow: 0 2px 8px rgba(0,0,0,0.3);
+}
+
+.emoji-btn {
+    background: none;
+    border: none;
+    font-size: 1.2rem;
+    cursor: pointer;
+    padding: 2px 4px;
+    border-radius: 4px;
+}
+
+.emoji-btn:hover {
+    background: #36393f;
+}
+
+/* Message Input */
+.message-input-area,
+.thread-input-area {
+    padding: 12px 20px;
+    border-top: 1px solid #202225;
+    display: flex;
+    gap: 8px;
+    align-items: flex-end;
+}
+
+.message-textarea {
+    flex: 1;
+    resize: none;
+    background: #40444b;
+    border: none;
+    border-radius: 8px;
+    padding: 10px 12px;
+    color: #dcddde;
+    font-size: 0.9rem;
+    font-family: inherit;
+    outline: none;
+}
+
+.message-textarea:focus {
+    box-shadow: 0 0 0 2px #7289da;
+}
+
+.message-textarea::placeholder {
+    color: #72767d;
+}
+
+.send-btn {
+    background: #7289da;
+    color: #fff;
+    border: none;
+    border-radius: 6px;
+    padding: 10px 16px;
+    font-weight: 600;
+    cursor: pointer;
+    font-size: 0.85rem;
+}
+
+.send-btn:hover:not(:disabled) {
+    background: #677bc4;
+}
+
+.send-btn:disabled {
+    opacity: 0.5;
+    cursor: not-allowed;
+}
+
+/* Thread Panel */
+.thread-panel {
+    width: 25%;
+    min-width: 280px;
+    background: #2f3136;
+    color: #dcddde;
+    display: flex;
+    flex-direction: column;
+    border-left: 1px solid #202225;
+}
+
+.thread-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    padding: 12px 16px;
+    border-bottom: 1px solid #202225;
+}
+
+.thread-header h3 {
+    margin: 0;
+    font-size: 1rem;
+    color: #fff;
+}
+
+.close-btn {
+    background: none;
+    border: none;
+    color: #b9bbbe;
+    font-size: 1.2rem;
+    cursor: pointer;
+    padding: 4px 8px;
+    border-radius: 4px;
+}
+
+.close-btn:hover {
+    background: #36393f;
+    color: #fff;
+}
+
+.thread-root-message {
+    padding: 12px 16px;
+    border-bottom: 1px solid #202225;
+    background: #36393f;
+}
+
+.thread-root-message .message-author {
+    font-size: 0.85rem;
+}
+
+.thread-root-message .message-content {
+    font-size: 0.85rem;
+    color: #b9bbbe;
+}
+
+.thread-replies {
+    flex: 1;
+    overflow-y: auto;
+    padding: 12px 16px;
+    display: flex;
+    flex-direction: column;
+    gap: 8px;
+}
+
+.thread-reply {
+    padding: 8px;
+    border-radius: 4px;
+}
+
+.thread-reply:hover {
+    background: #36393f;
+}
+
+.thread-reply .message-header {
+    display: flex;
+    align-items: baseline;
+    gap: 8px;
+}
+
+.thread-reply .message-content {
+    margin-top: 2px;
+    font-size: 0.85rem;
+}
+

